  load: () => ipcRenderer.invoke('tt:store-load'),
  save: (data) => ipcRenderer.invoke('tt:store-save', data),
  del: () => ipcRenderer.invoke('tt:store-del'),
  path: () => ipcRenderer.invoke('tt:store-path'),
